list_dashboard_banners.code:
import (
	"fmt"
)

resp, err := client.DashboardBanners().ListDashboardBanners(ctx, nil)
if err != nil {
	log.Fatal(err)
}
for _, row := range resp.Map().(map[string]any)["banners"].([]any) {
	banner := row.(map[string]any)
	fmt.Println(banner["key"], banner["position"], banner["active"], banner["title"])
}

